insert into public.products
  (slug, brand_id, name, color, color_hex, color_group, style_code, category, price, old_price,
   origin, material, fit, order_lead, description_ru, description_uz, description_en, is_new, is_featured, is_active, created_at) values
  ('boss-mesh-trainers-ribbed-sole-black-grey', (select id from public.brands where slug = 'boss'), 'Mesh trainers with ribbed sole', 'Black / grey', '#2B2B2B', 'black', 'HB-50568928', 'sneakers', 1380000, null, null, 'Mesh upper (100% polyester), smooth trims, lightweight ribbed rubber outsole', null, '15–20', 'Беговые кроссовки BOSS с сетчатым верхом, гладкими вставками и лёгкой рифлёной подошвой. Оригинал, артикул 50568928, цвет 015.', 'Toʻrsimon ustki qismi, silliq qoʻshimchalari va yengil qovurgʻali tagligi bor BOSS yugurish krossovkalari. Original, artikul 50568928, rang 015.', 'Running-inspired BOSS trainers with mesh uppers, smooth trims and a lightweight ribbed outsole. Original, style 50568928, colour 015.', true, true, true, now() - interval '0 minutes'),
  ('porsche-x-boss-stretch-cotton-cap-black', (select id from public.brands where slug = 'boss'), 'Porsche x BOSS stretch-cotton cap', 'Black', '#111111', 'black', 'HB-50572432', 'caps-hats', 820000, null, null, '98% cotton, 2% elastane (peached twill); lining 100% polyester', null, '15–20', 'Кепка из коллаборации Porsche x BOSS: персиковый эластичный хлопковый твил, тональный глянцевый логотип, изогнутый козырёк и фирменная застёжка. Артикул 50572432.', 'Porsche x BOSS hamkorligidagi kepka: yumshoq elastik paxta tvil, bir xil rangdagi yaltiroq logotip, egilgan soyabon va brend qisqichi. Artikul 50572432.', 'A Porsche x BOSS cap in peached stretch-cotton twill with a gloss-effect tonal logo, curved visor and branded closure. Style 50572432.', true, true, true, now() - interval '1 minutes'),
  ('boss-grained-leather-loafers-dark-brown', (select id from public.brands where slug = 'boss'), 'Grained-leather loafers', 'Dark brown', '#4A3B33', 'brown', 'HB-50536173', 'classic-shoes', 1710000, null, null, 'Grained cow leather upper, lining and insole; synthetic rubber sole', null, '15–20', 'Лоферы BOSS из зернистой кожи: полностью на кожаной подкладке, с тиснёным логотипом сбоку и светлой резиновой подошвой. Артикул 50536173.', 'Donador teridan BOSS loferlari: toʻliq teri astarli, yon tomonida bosma logotip, ochiq rangli rezina taglik. Artikul 50536173.', 'BOSS slip-on loafers in grained leather, fully leather-lined, with an embossed side logo and a light rubber sole. Style 50536173.', true, true, true, now() - interval '2 minutes'),
  ('boss-x-aston-martin-polo-cotton-silk-light-beige', (select id from public.brands where slug = 'boss'), 'BOSS x Aston Martin polo in cotton and silk', 'Light beige', '#DAD6CC', 'beige', 'HB-50548616', 'polos', 1410000, null, null, '85% cotton, 15% silk, quilted texture', 'regular', '15–20', 'Поло из коллаборации BOSS x Aston Martin: хлопок с шёлком, стёганая фактура и фирменные «крылья» Aston Martin на груди. Прямой крой. Артикул 50548616.', 'BOSS x Aston Martin hamkorligidagi polo: ipak qoʻshilgan paxta, qavima tekstura va koʻkragida Aston Martin «qanotlari». Toʻgʻri bichim. Artikul 50548616.', 'A BOSS x Aston Martin polo in cotton and silk with a quilted texture and the Aston Martin wings on the chest. Regular fit. Style 50548616.', true, true, true, now() - interval '3 minutes'),
  ('boss-zip-up-sweatshirt-jacket-black', (select id from public.brands where slug = 'boss'), 'Zip-up sweatshirt jacket', 'Black', '#141414', 'black', null, 'hoodies-sweatshirts', 1290000, null, null, null, 'regular', '15–20', 'Чёрная куртка-толстовка BOSS на молнии с воротником-стойкой. Легко сочетается с футболкой и джинсами.', 'Tik yoqali, zamokli qora BOSS sviter-kurtka. Futbolka va jinsi bilan oson uygʻunlashadi.', 'A black BOSS zip-up sweatshirt jacket with a stand collar. Easy over a T-shirt and jeans.', true, false, true, now() - interval '4 minutes'),
  ('mizuno-gore-tex-trail-shoes-grey', (select id from public.brands where slug = 'mizuno'), 'GORE-TEX trail shoes', 'Grey', '#77787B', 'grey', null, 'sneakers', 1950000, null, null, 'Knit upper with a GORE-TEX waterproof membrane, lugged rubber outsole', null, '15–20', 'Кроссовки Mizuno с мембраной GORE-TEX: не промокают, держат тепло и уверенно цепляются за мокрый асфальт и тропу благодаря протектору.', 'GORE-TEX membranali Mizuno krossovkalari: suv oʻtkazmaydi, issiqni saqlaydi, chuqur protektori hoʻl yoʻl va soʻqmoqda ishonchli ushlaydi.', 'Mizuno trail shoes with a GORE-TEX membrane: waterproof, warm, and a deep lugged outsole that grips wet streets and trails.', true, false, true, now() - interval '5 minutes'),
  ('ramsey-half-zip-merino-sweater-navy', (select id from public.brands where slug = 'ramsey'), 'Half-zip merino sweater', 'Navy', '#1D2433', 'navy', 'RM-10157838', 'knitwear', 780000, null, 'TR', 'Extra-fine merino wool blend, flat knit', 'regular', '15–20', 'Тонкий свитер Ramsey из экстратонкой мериносовой шерсти с воротником-стойкой на молнии — лёгкий, очень мягкий, хорошо сидит под пиджаком и курткой. Есть варианты с одной или двумя молниями.', 'Ramsey ning ekstra ingichka merinos junidan yupqa sviteri, zamokli tik yoqa bilan — yengil, juda yumshoq, pidjak va kurtka ostida yaxshi turadi. Bir yoki ikki zamokli variantlari bor.', 'A fine Ramsey sweater in extra-fine merino wool with a zipped stand collar: light, very soft and made to sit under a blazer or jacket. Available with one or two zips.', true, true, true, now() - interval '6 minutes'),
  ('ramsey-wool-overshirt-suit-navy', (select id from public.brands where slug = 'ramsey'), 'Wool overshirt suit, two-piece', 'Navy', '#1E2433', 'navy', 'RM-10151002', 'suits-blazers', 3070000, null, 'TR', '100% wool', 'regular', '15–20', 'Костюм-двойка Ramsey из 100% шерсти: куртка-рубашка с накладными карманами и брюки в тон. Свободный casual-крой — можно носить вместе или по отдельности.', 'Ramsey ning 100% jundan ikki qismli kostyumi: ustki choʻntakli koʻylak-kurtka va bir xil rangdagi shim. Erkin casual bichim — birga ham, alohida ham kiyish mumkin.', 'A Ramsey two-piece in 100% wool: an overshirt jacket with patch pockets and matching trousers. Relaxed casual cut, to wear together or apart.', true, true, true, now() - interval '7 minutes'),
  ('ramsey-pique-polo-shirt-petrol', (select id from public.brands where slug = 'ramsey'), 'Cotton piqué polo shirt', 'Petrol', '#1F5D6B', 'blue', 'RM-10157221', 'polos', 550000, null, 'TR', '100% cotton piqué', 'slim', '15–20', 'Поло Ramsey цвета «петроль» из 100% хлопкового пике: дышит, держит форму и подходит и для офиса, и для выходных.', 'Ramsey ning «petrol» rangli 100% paxta pike polosi: havo oʻtkazadi, shaklini saqlaydi, ofisga ham, dam olish kunlariga ham mos.', 'A Ramsey polo in petrol blue, 100% cotton piqué: breathable, holds its shape, right for the office and the weekend.', true, false, true, now() - interval '8 minutes'),
  ('ramsey-slim-chino-trousers-navy', (select id from public.brands where slug = 'ramsey'), 'Slim chino trousers', 'Navy', '#1E2536', 'navy', 'RM-10164268', 'trousers', 650000, null, 'TR', 'Cotton blend', 'slim', '15', 'Чиносы Ramsey приталенного кроя из мягкого хлопкового смесового твила — от офиса до вечера. Есть в тёмно-синем и чёрном.', 'Ramsey ning yumshoq aralash paxta tvildan torroq bichimli chinoslari — ofisdan kechgacha. Toʻq koʻk va qora ranglarda.', 'Ramsey chinos in a soft cotton-blend twill with a slim cut, from the office to the evening. In navy and black.', true, true, true, now() - interval '9 minutes'),
  ('ramsey-slim-chino-trousers-black', (select id from public.brands where slug = 'ramsey'), 'Slim chino trousers', 'Black', '#151515', 'black', 'RM-10164268', 'trousers', 650000, null, 'TR', 'Cotton blend', 'slim', '15', 'Чиносы Ramsey приталенного кроя из мягкого хлопкового смесового твила — от офиса до вечера. Есть в чёрном и тёмно-синем.', 'Ramsey ning yumshoq aralash paxta tvildan torroq bichimli chinoslari — ofisdan kechgacha. Qora va toʻq koʻk ranglarda.', 'Ramsey chinos in a soft cotton-blend twill with a slim cut, from the office to the evening. In black and navy.', true, false, true, now() - interval '10 minutes'),
  ('adidas-fleece-hooded-tracksuit-black', (select id from public.brands where slug = 'adidas'), 'Fleece hooded tracksuit, hoodie and pants', 'Black', '#151515', 'black', null, 'hoodies-sweatshirts', 1050000, null, null, 'Cotton-blend fleece', 'regular', '15–20', 'Комплект adidas: флисовое худи на молнии с капюшоном и брюки в тон, тональный логотип. Тёплый и мягкий — на каждый день.', 'adidas toʻplami: kapyushonli zamokli flis xudi va bir xil rangdagi shim, tonal logotip. Issiq va yumshoq — har kuni uchun.', 'An adidas set: a full-zip fleece hoodie and matching pants with a tonal logo. Warm and soft, for every day.', true, false, true, now() - interval '11 minutes')
on conflict (slug) do nothing;

